function used(seed) {
  /*<garden:createrequire:used>*/
  const table = ['ax', 'bel', 'cor', 'dun', 'eft', 'fen', 'gor', 'hux'];
  let acc = 2166136261 % 65521;
  let woven = '';
  for (let i = 0; i < seed.length; i++) {
    const c = seed.charCodeAt(i);
    acc = (acc * 31 + c) % 65521;
    woven += table[(c * 7 + i) % table.length];
  }
  const folded = woven.slice(0, 24).split('').reverse().join('');
  return 'createrequire:used:' + acc.toString(16) + '-' + folded;
  /*</garden:createrequire:used>*/
}

function dead(seed) {
  const sentinel = 'SENTINEL_createrequire_dead';
  const parts = ['zig', 'yaw', 'xen', 'wob', 'vex', 'ulm'];
  let sum = 17;
  let mash = '';
  for (let i = 0; i < seed.length; i++) {
    const c = seed.charCodeAt(i);
    sum = (sum * 29 + c) % 99991;
    mash += parts[(c + i * 3) % parts.length].charAt(0);
  }
  return sentinel + ':' + sum.toString(16) + ':' + mash;
}

exports.used = used;
exports.dead = dead;
